import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadZodiacData(){const e=readFileSync(resolve(__dirname,"../../jahangir-zodiac-coins-explorer/zodiac-data.js"),"utf-8");return new Function(e+"\nreturn { JAHANGIR_INFO, ZODIAC_SIGNS, TIMELINE_EVENTS, REFERENCES };")()}describe("Jahangir Zodiac Coins Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadZodiacData()}),describe("JAHANGIR_INFO metadata",()=>{it("contains correct Jahangir Zodiac coins metadata",()=>{expect(e.JAHANGIR_INFO.id).toBe("jahangir-zodiac-coins"),expect(e.JAHANGIR_INFO.title).toContain("Jahangir"),expect(e.JAHANGIR_INFO.reignPeriod).toContain("1605"),expect(e.JAHANGIR_INFO.primaryMints).toContain("Agra")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.JAHANGIR_INFO.quickStats)).toBe(!0),expect(e.JAHANGIR_INFO.quickStats.length).toBe(6)})}),describe("ZODIAC_SIGNS array",()=>{it("contains all 12 astrological zodiac signs",()=>{expect(Array.isArray(e.ZODIAC_SIGNS)).toBe(!0),expect(e.ZODIAC_SIGNS.length).toBe(12);const t=e.ZODIAC_SIGNS.find(e=>"aries"===e.id);expect(t).toBeDefined(),expect(t.reverseInscription).toContain("Agra");const a=e.ZODIAC_SIGNS.find(e=>"leo"===e.id);expect(a).toBeDefined(),expect(a.symbol).toContain("Lion")})}),describe("TIMELINE_EVENTS & REFERENCES",()=>{it("contains historical timeline events and references",()=>{expect(Array.isArray(e.TIMELINE_EVENTS)).toBe(!0),expect(e.TIMELINE_EVENTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});